"use strict";function geoDatasetFilterSelectOptions(e,t){const n={plugins:["remove_button"],maxOptions:100,placeholder:e.dataset.placeholder||"Any",hidePlaceholder:!0};if(e.dataset.geodatasetFilter!=="autocomplete")return n;const d=e.dataset.autocompleteUrl;return Object.assign(n,{valueField:"value",labelField:"text",searchField:["text"],loadThrottle:250,shouldLoad:a=>a.length>0,load(a,l){t(`${d}?q=${encodeURIComponent(a)}`,{headers:{Accept:"application/json"}}).then(o=>o.ok?o.json():{results:[]}).then(o=>l(o.results||[])).catch(()=>l())}})}function initGeoDatasetFilterSelects(e){typeof TomSelect>"u"||e.querySelectorAll("select[data-geodataset-filter]").forEach(t=>{t.tomselect||new TomSelect(t,geoDatasetFilterSelectOptions(t,fetch))})}document.addEventListener("DOMContentLoaded",()=>initGeoDatasetFilterSelects(document));
